/* ================================================================ */
/* INTERIOR tileset                                                 */
/* ================================================================ */
enum {
  MT_I_VOID,  /* black outside the room */
  MT_I_FLOOR,  /* warm wooden planks */
  MT_I_FLOOR2,  /* light tile floor (shop, hearth hall, almanac house) */
  MT_I_WALL_TOP,  /* upper back wall (wallpaper, dark top trim) */
  MT_I_WALL,  /* lower back wall with wainscot/baseboard, directly above the floor */
  MT_I_WINDOW,  /* window in the upper wall row */
  MT_I_WALL_CLOCK,  /* upper wall with clock */
  MT_I_PAINTING,  /* upper wall with framed picture */
  MT_I_DOORMAT,  /* exit mat (on FLOOR) at the bottom edge */
  MT_I_COUNTER,  /* counter middle (seamless), on FLOOR2 */
  MT_I_COUNTER_L,  /* counter left end */
  MT_I_COUNTER_R,  /* counter right end */
  MT_I_TERRAIN_COUNT
};
