/* ================================================================ */
enum {
  MT_CV_FLOOR,  /* cave floor (+ FLOOR2 crystal grit, FLOOR3 pebbles and a crack) */
  MT_CV_FLOOR2,
  MT_CV_FLOOR3,
  MT_CV_MOSS,  /* glowmoss carpet: wild kin roam here; top layer hides legs */
  MT_CV_ROCK,  /* rock mass, the cave roof seen from above (solid) */
  MT_CV_WALL,  /* rock wall face (solid); put it on the floor side below ROCK */
  MT_CV_WALL_CRYSTAL,  /* wall face with a glowing crystal vein (solid) */
  MT_CV_CRYSTAL,  /* crystal outcrop growing out of the floor (solid) */
  MT_CV_LEDGE,  /* rock ledge: walk DOWN onto it to hop over; tiles horizontally */
  MT_CV_LEDGE_L,
  MT_CV_LEDGE_R,
  MT_CV_MOUTH,  /* exit mat: daylight and blown-in snow at the cave mouth (A_EXIT) */
  MT_CV_VOID,  /* outside the cave */
  MT_CV_POOL,  /* the starlit pool of the Starfall Grotto (solid); POOL_* have a stone rim */
  MT_CV_POOL_N,
  MT_CV_POOL_S,
  MT_CV_POOL_W,
  MT_CV_POOL_E,
  MT_CV_POOL_NW,
  MT_CV_POOL_NE,
  MT_CV_POOL_SW,
  MT_CV_POOL_SE,
  MT_CV_TERRAIN_COUNT
};
