/* ================================================================ */
/* GRIM tileset                                                     */
/* ================================================================ */
enum {
  MT_GR_ASH,  /* drifted ash (+ ASH2 cinders, ASH3 a bone chip and an ember) */
  MT_GR_ASH2,
  MT_GR_ASH3,
  MT_GR_ASH_GRASS,  /* dead grass on ash; wild kin roam; top layer = front blades */
  MT_GR_SCORCH,  /* burnt earth with cracks */
  MT_GR_EMBERS,  /* smouldering cracks, animated (walkable) */
  MT_GR_COBBLE,  /* old cobbles of the ash road and the Duskmere square */
  MT_GR_GRAVE_SOIL,  /* dark loam with fallen leaves (Gravewood floor, + variant) */
  MT_GR_GRAVE_SOIL2,
  MT_GR_GRAVE_BRUSH,  /* dead bracken; wild kin roam; top layer = front fronds */
  MT_GR_MUD,  /* peat mud (+ MUD2 with a puddle and foxfire specks) */
  MT_GR_MUD2,
  MT_GR_MOSS,  /* moss carpet on the mud */
  MT_GR_MIRE_REEDS,  /* reeds in the mud; wild kin roam; top layer = front stalks */
  MT_GR_DECK,  /* weathered planks (Duskmere platforms) */
  MT_GR_GNARL_TOP,  /* 16x32 dead oak: TOP above BOTTOM (overlay) */
  MT_GR_GNARL_BOTTOM,
  MT_GR_SNAG_TOP,  /* 16x32 charred pine with ember cracks (overlay; forest walls) */
  MT_GR_SNAG_BOTTOM,
  MT_GR_CYPRESS_TOP,  /* 16x32 swamp cypress with hanging moss (overlay) */
  MT_GR_CYPRESS_BOTTOM,
  MT_GR_LEDGE,  /* one-way ash ledge: walk DOWN onto it to hop over */
  MT_GR_LEDGE_L,
  MT_GR_LEDGE_R,
  MT_GR_CRAG,  /* rock wall with an ash lip (solid); CRAG_FACE stacks below */
  MT_GR_CRAG_FACE,
  MT_GR_TERRAIN_COUNT
};
