/* ================================================================ */
/* CRYPT tileset                                                    */
/* ================================================================ */
enum {
  MT_CR_VOID,  /* black outside the rooms */
  MT_CR_WALL_TOP,  /* top of a crypt wall (dark stone) */
  MT_CR_WALL,  /* wall face: violet bricks above a shadowed footing */
  MT_CR_NICHE,  /* wall face with a skull niche and a candle */
  MT_CR_BONE_WALL,  /* wall face of stacked skulls and long bones (the Ossuary) */
  MT_CR_WISP_WALL,  /* wall face split by a glowing green foxfire crack */
  MT_CR_FLOOR,  /* cold violet flagstones */
  MT_CR_FLOOR2,  /* cracked flagstones with bone dust */
  MT_CR_BLOCK,  /* a maze block seen from above: top face and a brick front */
  MT_CR_FAKE_BLOCK,  /* identical to BLOCK but walkable (a false wall) */
  MT_CR_GHOST_FLOOR,  /* identical to FLOOR but solid (an unseen wall) */
  MT_CR_DOORMAT,  /* worn threshold slab (exit mat) */
  MT_CR_CARPET,  /* red runner with gold edges */
  MT_CR_STAIRS_UP,  /* stone steps rising into the wall (door) */
  MT_CR_STAIRS_DOWN,  /* steps falling away into the dark (door) */
  MT_CR_ARCH,  /* a dark archway (door) */
  MT_CR_PILLAR_TOP,  /* column capital (upper cell) */
  MT_CR_PILLAR,  /* column shaft (lower cell) */
  MT_CR_BONEDUST,  /* flagstones drifted with bone dust and shed bones (wild kin roam) */
  MT_CR_TERRAIN_COUNT
};
